1	import { execFileSync } from 'node:child_process';
2	import { parseStatusOutput } from './status-output.mjs';
3	
4	// Reads `supabase status -o json` for verify.mjs, verify-gym.mjs and verify-freezes.mjs (QA-9 phase 3N gap G5, fix F4).
5	// A failed command throws an error that carries what the command printed: its stdout, its output list, and a message
6	// that can quote them. That output holds keys, so the thrown value is dropped unbound and unread, and a new error with
7	// one fixed message, no cause and no field takes its place. What a successful command printed goes to parseStatusOutput
8	// outside that catch, so a bad parse keeps the helper's own fixed refusal. Loading this module runs nothing: the real
9	// command is only the default of `run`, used when a suite calls the export with no argument; tests pass a fake. The
10	// command, its arguments and its options are the ones the suites ran. It decides no target: each suite asserts API_URL.
11	
12	const FAILED = 'supabase status -o json failed; its error and output are not shown because they can hold keys';
13	const FAILED_RUN = Symbol('failed run');
14	
15	/** What the status command printed, or FAILED_RUN. The thrown value is never bound, so nothing here can read it. */
16	function capturedOrFailed(run) {
17	  try {
18	    return run('pnpm', ['exec', 'supabase', 'status', '-o', 'json'], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] });
19	  } catch {
20	    return FAILED_RUN;
21	  }
22	}
23	
24	/** The local stack's status object. A failed command throws the fixed message above; bad output, the helper's own. */
25	export function readLocalStatus(run = execFileSync) {
26	  const output = capturedOrFailed(run);
27	  if (output === FAILED_RUN) throw new Error(FAILED);
28	  return parseStatusOutput(output);
29	}
